25: static NSString *ISStamp(void) {
26:     NSDateFormatter *f=[NSDateFormatter new];
27:     f.locale=[NSLocale localeWithLocaleIdentifier:@"en_US_POSIX"];
28:     f.dateFormat=@"yyyy-MM-dd HH:mm:ss.SSS ZZZZ";
29:     return [f stringFromDate:[NSDate date]];
30: }
31: static void ISWrite(NSString *line) {
32:     if (!line || !gWriter) return;
33:     dispatch_async(gWriter, ^{
34:         @autoreleasepool {
35:             NSFileManager *fm=[NSFileManager defaultManager];
36:             if (![fm createDirectoryAtPath:kDir withIntermediateDirectories:YES attributes:nil error:nil]) return;
37:             unsigned long long bytes=[[fm attributesOfItemAtPath:kLog error:nil] fileSize];
38:             if (bytes>=kRotate) {
39:                 NSString *old=[kDir stringByAppendingPathComponent:@"events.previous.log"];
40:                 [fm removeItemAtPath:old error:nil];
41:                 [fm moveItemAtPath:kLog toPath:old error:nil];
42:             }
43:             if (![fm fileExistsAtPath:kLog]) [fm createFileAtPath:kLog contents:nil attributes:nil];
44:             NSFileHandle *h=[NSFileHandle fileHandleForWritingAtPath:kLog];
45:             if (!h) return;
46:             @try { [h seekToEndOfFile]; [h writeData:[[line stringByAppendingString:@"\n"] dataUsingEncoding:NSUTF8StringEncoding]]; [h closeFile]; }
47:             @catch (NSException *e) { @try { [h closeFile]; } @catch (NSException *ignored) {} }
48:         }
49:     });
50: }
51: static void ISEmit(NSString *type, NSString *details) {
52:     if (gCount>=kCap) return;
53:     ++gCount; ++gSequence;
54:     NSString *line=[NSString stringWithFormat:@"%@ [IslandScope 1.4.2] #%lu %@ %@",ISStamp(),(unsigned long)gSequence,type,details?:@""];
55:     ISWrite(line);
56:     // Console output is deliberately limited to anomalies / startup to reduce SpringBoard overhead.
57:     if ([type isEqualToString:@"ANOMALY"] || [type isEqualToString:@"START"]) NSLog(@"%@",line);
58: }
59: static void ISReadConfig(void) {
60:     NSTimeInterval now=NSDate.date.timeIntervalSince1970;
61:     if (now-gLastConfig<3.0) return;
62:     gLastConfig=now;
63:     NSDictionary *d=[NSDictionary dictionaryWithContentsOfFile:kCfg];
64:     gEnabled=d[@"enabled"] ? [d[@"enabled"] boolValue] : YES;
65:     gDeep=d[@"deep"] ? [d[@"deep"] boolValue] : YES;
66:     ISPhaseUpdate();
67: }
